from pwn import *

def setup_vm():
    # Connect to the challenge server
    try:
        conn = remote('pwn.chal.csaw.io', 23750, timeout=30)

        print("Connected to challenge server. Waiting for VM setup...")

        # Read output until we get the port
        while True:
            try:
                line = conn.recvline(timeout=5).decode().strip()
                print(line)
                if 'localhost:' in line:
                    port = line.split(':')[1].strip()
                    print(f"\nExtracted port: {port}")
                    with open('/home/ctfplayer/vm_port.txt', 'w') as f:
                        f.write(port)
                    return port
            except EOFError:
                print("Connection closed unexpectedly")
                break
            except Exception as e:
                print(f"Error reading line: {str(e)}")
                break

    except Exception as e:
        print(f"Failed to connect: {str(e)}")
        return None
    finally:
        try:
            conn.close()
        except:
            pass

if __name__ == '__main__':
    port = setup_vm()
    if port:
        print(f"\nVM should be accessible at localhost:{port}")

