#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <errno.h>

#define KRYPTO_RNG_CMD 0x1337
#define BUFFER_SIZE 0x100

struct rng_params {
    void *buf;
    size_t len;
};

void print_hex(unsigned char *buf, size_t len) {
    for(size_t i = 0; i < len; i++) {
        printf("%02x", buf[i]);
        if((i + 1) % 16 == 0) printf("\n");
        else printf(" ");
    }
    printf("\n");
}

int main() {
    int fd;
    unsigned char buffer[BUFFER_SIZE];
    struct rng_params params;

    // Open the device
    fd = open("/dev/krypto", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/krypto");
        return 1;
    }

    // Initialize parameters
    memset(buffer, 0, BUFFER_SIZE);
    params.buf = buffer;
    params.len = BUFFER_SIZE;

    // Call ioctl
    if (ioctl(fd, KRYPTO_RNG_CMD, &params) < 0) {
        perror("ioctl failed");
        close(fd);
        return 1;
    }

    // Print received data
    printf("Received %zu bytes of random data:\n", BUFFER_SIZE);
    print_hex(buffer, BUFFER_SIZE);

    close(fd);
    return 0;
}

