context.log_level = 'debug'

def wait_for_ssh(hostname, port, max_attempts=60):
    for attempt in range(max_attempts):
        try:
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            ssh.connect(
                hostname,
                port=port,
                username='user',
                password='user',
                timeout=10,
                allow_agent=False,
                look_for_keys=False,
                banner_timeout=60
            )
            return ssh
        except Exception as e:
            print(f"SSH connection attempt {attempt + 1}/{max_attempts} failed: {e}")
            time.sleep(2)
    raise Exception("Failed to connect via SSH after all attempts")

def run_command(ssh, command):
    chan = ssh.get_transport().open_session()
    chan.exec_command(command)
    stdout_data = ''
    stderr_data = ''

    while True:
        if chan.recv_ready():
            stdout_data += chan.recv(4096).decode('utf-8')
        if chan.recv_stderr_ready():
            stderr_data += chan.recv_stderr(4096).decode('utf-8')
        if chan.exit_status_ready():
            break

    return stdout_data, stderr_data, chan.recv_exit_status()

